// Crusaders Mainframe — how long the lock stays released, and the two bounds
// that cannot be argued with.
//
// WHY NOT delay(3000)
// -------------------
// Carl's sketch releases the lock, `delay(3000)`, and locks again. For those
// three seconds the board reads no scanner bytes, answers no watchdog and
// notices no WiFi change — and if it resets inside the delay, the lock is left
// released with nothing running to take it back. The window is a DEADLINE here
// and the loop keeps running through it.
//
// RE-ARM NEVER SHORTENS
// ---------------------
// A second member scanning while the door is already released must not cut the
// first one's window short — they are standing in the doorway. So a re-arm
// takes the LATER of the two deadlines. A shorter request while released is
// therefore a no-op, not a shortening.
//
// THE HARD CAP IS TWO BOUNDS, NOT ONE
// -----------------------------------
// Per request: a single answer can never ask for more than the cap. That alone
// is not enough — "re-arm never shortens" plus a scanner that repeats is a door
// that stays open for as long as somebody keeps waving a phone at it, one
// legal 3-second extension at a time. So the release WINDOW is also bounded:
// no deadline may ever fall later than the cap after the moment the door was
// first released. Both bounds are mutation-proved; remove either and a member
// can hold a door open indefinitely with no single request that breaks a rule.
//
// No Arduino headers, no heap. Compiles for Xtensa and the host test runner.

#ifndef CRUSADERS_GATELOGIC_UNLOCKTIMER_H
#define CRUSADERS_GATELOGIC_UNLOCKTIMER_H

#include <stdint.h>

#include "../timebase/TimeBase.h"

namespace gatelogic {

class UnlockTimer {
public:
  /// `hardCapMs` bounds both a single request and the whole release window.
  explicit UnlockTimer(uint32_t hardCapMs) : hardCapMs_(hardCapMs) {}

  /// Release the lock for `requestedMs`, or extend an existing release.
  ///
  /// Returns true when the door was LOCKED and is now released — the edge the
  /// composition root turns into a relay write and an LED change. A re-arm
  /// returns false: nothing changed about the door, only about when it closes.
  bool request(uint32_t nowMs, uint32_t requestedMs) {
    const uint32_t bounded = requestedMs > hardCapMs_ ? hardCapMs_ : requestedMs;

    if (!released_) {
      released_ = true;
      openedAtMs_ = nowMs;
      until_.arm(nowMs, bounded);
      return true;
    }

    // Already released. Never shorter than what is left, and never later than
    // the cap after this window began.
    const uint32_t left = until_.remaining(nowMs);
    const uint32_t sinceOpen = tb::since(nowMs, openedAtMs_);
    const uint32_t capLeft = sinceOpen >= hardCapMs_ ? 0U : hardCapMs_ - sinceOpen;
    uint32_t extend = bounded > left ? bounded : left;
    if (extend > capLeft) {
      extend = capLeft;
    }
    until_.arm(nowMs, extend);
    return false;
  }

  /// Advance the window. Returns true on the released -> locked edge, exactly
  /// once, so the caller can write the relay and queue nothing twice.
  bool tick(uint32_t nowMs) {
    if (!released_ || !until_.expired(nowMs)) {
      return false;
    }
    released_ = false;
    until_.disarm();
    return true;
  }

  bool released() const { return released_; }

  uint32_t remainingMs(uint32_t nowMs) const { return until_.remaining(nowMs); }

  /// How long the lock has been released in this window, for the event the
  /// queue carries. Zero when locked.
  uint32_t releasedForMs(uint32_t nowMs) const { return released_ ? tb::since(nowMs, openedAtMs_) : 0U; }

private:
  uint32_t hardCapMs_;
  tb::Deadline until_;
  /// When THIS release window began. A separate field rather than "the deadline
  /// minus the duration", because the duration changes on every re-arm and the
  /// cap has to be measured from the start of the window, not from the last
  /// extension of it.
  uint32_t openedAtMs_ = 0U;
  bool released_ = false;
};

} // namespace gatelogic

#endif // CRUSADERS_GATELOGIC_UNLOCKTIMER_H
